#!/usr/bin/env node
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import {spawnSync} from "node:child_process";

const ROOT=process.cwd(), OUT=path.join(ROOT,"artifacts","browser-qa"), VIEWPORTS=[[360,800],[393,873],[412,915]];
const read=f=>fs.readFileSync(path.join(ROOT,f),"utf8");
const esc=s=>s.replace(/<\/script/gi,"<\\/script");
function chrome(){const configured=String(process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH||"").trim();if(configured&&fs.existsSync(configured))return configured;for(const n of ["google-chrome","google-chrome-stable","chromium","chromium-browser"]){const p=spawnSync("bash",["-lc",`command -v ${n}`],{encoding:"utf8"});if(p.status===0&&p.stdout.trim())return p.stdout.trim();}throw new Error("Headless Chrome/Chromium is required for Daily Dungeon portrait QA");}
const manifest=JSON.parse(read("config/monster-portrait-registry.json")), tuple=manifest.tupleSchema;
const records=Object.values(manifest.groups).flatMap(g=>(g||[]).map(row=>Object.fromEntries(tuple.map((k,i)=>[k,row[i]]))));
const expected=Object.fromEntries(records.filter(r=>r.status==="existing").map(r=>[r.portraitKey,r.path]));
const primary=esc(read("build/gameplay-core-primary.82733de23722.js")), secondary=esc(read("build/gameplay-core-secondary.5b669993c6ab.js")), css=esc(read("css/fixed-slot-battlefield-rendering-v2.css"));
function html(w,h){const rows=JSON.stringify(records);return `<!doctype html><meta name="viewport" content="width=${w},initial-scale=1"><style>html,body{margin:0;width:100%;height:100%;background:#120e09;color:#fff}#battlePage{width:100%;height:100%}.battle-monster{position:relative;width:160px;height:220px}.v174-battle-art{position:absolute;inset:0;background-repeat:no-repeat;background-position:center;background-size:contain;opacity:1;visibility:visible}.battle-monster-name{position:absolute;bottom:0}</style><style>${css}</style><section id="battlePage"><div id="battleMonsterArea"></div></section><div id="qa">QA_PENDING</div><script>window.__dailyRegistryRows=${rows};window.monsters=[];window.currentBattleMonsters=[];window.FourSymbolsAccountSave={getActiveUid:()=>"qa",saveKey:()=>"qa"};window.FourSymbolsFeatures={ensureAssets:async()=>{}};window.bumpBattleRuntimeMetric=()=>{};</script><script src="${process.env.DEV_BASE_URL||"http://127.0.0.1:4174"}/build/gameplay-core-primary.82733de23722.js"></script><script src="${process.env.DEV_BASE_URL||"http://127.0.0.1:4174"}/build/gameplay-core-secondary.5b669993c6ab.js"></script><script>(async()=>{const assert={equal:(a,b)=>{if(a!==b)throw new Error("equal: "+a+" !== "+b)},ok:(v,m)=>{if(!v)throw new Error(m||"assertion failed")},notEqual:(a,b)=>{if(a===b)throw new Error("notEqual")}};const out={viewport:{width:${w},height:${h}},types:{}};const registry={tupleSchema:${JSON.stringify(tuple)},groups:{}};for(const row of window.__dailyRegistryRows){(registry.groups[row.group]||(registry.groups[row.group]=[])).push(tuple.map(k=>row[k]));}window.v154InstallMonsterPortraitRegistry(registry);for(const type of ["exp","material","gold"]){out.types[type]={};for(const rank of ["regular","elite","boss"]){const key="daily."+type+"."+rank;window.monsters=[{portraitKey:key,rank}];window.currentBattleMonsters=[0];const area=document.getElementById("battleMonsterArea");area.replaceChildren();const card=document.createElement("div");card.id="battleMonster0";card.className="battle-monster";area.append(card);window.v154SyncMonsterPortraits();if(typeof window.vFixedSlotAfterBattleRender==="function")window.vFixedSlotAfterBattleRender();const art=card.querySelector(".v174-battle-art"),s=getComputedStyle(art),r=art.getBoundingClientRect(),path=card.dataset.monsterPortraitPath||"";assert.equal(card.dataset.monsterPortraitKey,key);assert.equal(path,${JSON.stringify(expected)}[key]);assert.ok(s.backgroundImage.includes(path));assert.notEqual(s.display,"none");assert.notEqual(s.visibility,"hidden");assert.ok(Number(s.opacity)>0&&r.width>0&&r.height>0);out.types[type][rank]={key,path,backgroundImage:s.backgroundImage,display:s.display,visibility:s.visibility,opacity:Number(s.opacity),width:r.width,height:r.height};}}document.getElementById("qa").textContent="QA_RESULT:"+btoa(unescape(encodeURIComponent(JSON.stringify(out))));})().catch(e=>{document.getElementById("qa").textContent="QA_ERROR:"+btoa(unescape(encodeURIComponent(JSON.stringify({error:String(e&&e.stack||e)}))));});</script>`;}
function run(w,h){fs.mkdirSync(OUT,{recursive:true});const fixture=path.join(OUT,`daily-dungeon-${w}x${h}.html`);fs.writeFileSync(fixture,html(w,h));const result=spawnSync(chrome(),["--headless=new","--no-sandbox","--disable-gpu","--disable-dev-shm-usage","--allow-file-access-from-files","--virtual-time-budget=2500",`--window-size=${w},${h}`,"--dump-dom",`${process.env.DEV_BASE_URL||"http://127.0.0.1:4174"}/artifacts/browser-qa/${path.basename(fixture)}`],{encoding:"utf8",timeout:30000,maxBuffer:32*1024*1024});assert.equal(result.status,0,result.stderr||"Chrome failed");const m=result.stdout.match(/<div id="qa">QA_RESULT:([^<]+)<\/div>/);assert.ok(m,"missing browser QA result: "+result.stdout.slice(-2400));const report=JSON.parse(decodeURIComponent(escape(Buffer.from(m[1],"base64").toString("binary"))));assert.ok(!report.error,report.error);return {report,fixture};}
const report={viewports:{}};for(const [w,h] of VIEWPORTS){const r=run(w,h);report.viewports[`${w}x${h}`]=r.report;const shot=spawnSync(chrome(),["--headless=new","--no-sandbox","--disable-gpu","--disable-dev-shm-usage","--allow-file-access-from-files","--virtual-time-budget=2500",`--window-size=${w},${h}`,`--screenshot=${path.join(OUT,`daily-dungeon-portraits-${w}x${h}.png`)}`,`${process.env.DEV_BASE_URL||"http://127.0.0.1:4174"}/artifacts/browser-qa/${path.basename(r.fixture)}`],{encoding:"utf8",timeout:30000});assert.equal(shot.status,0,shot.stderr||"screenshot failed");}fs.writeFileSync(path.join(OUT,"daily-dungeon-monster-portrait-browser-qa.json"),JSON.stringify(report,null,2));console.log("Daily Dungeon Monster Portrait Browser QA: PASS");
